import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// spec: specs/hal-engine-config-hooks/spec.md#7
it('preserves a non-Error rejection as the hook error cause and caller rejection', async () => {
  const reason = 'string boom';
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield -- This provider always rejects.
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw reason;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const session: ChatSession = {sessionId: 'test', userId: 'user', entries: []};
  let seen: Error | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {onError: async (_session, error) => { seen = error; }},
  });

  await expect(orchestrator.processMessage(session)).rejects.toBe(reason);
  expect(seen).toBeInstanceOf(Error);
  expect(seen?.cause).toBe(reason);
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/onErrorCause.test.ts"
